164	  readonly fit_score: number;
165	  // Score for each criterion.
166	  readonly criterion_scores: readonly CriterionScore[];
167	  // All facts used, each with a trust level.
168	  readonly evidence: readonly Evidence[];
169	  // Things the model could not confirm or is unsure about.
170	  readonly uncertainty_notes: readonly string[];
171	  // Optional first-contact message. Absent if no safe evidence to cite.
172	  readonly outreach?: OutreachDraft;
173	}
