208	// Default limits used when the caller sets none.
209	export const DEFAULT_RUN_CONFIG: RunConfig = {
210	  max_search_results: 100,
211	  max_enrichments: 15,
212	};
213	
214	// How many companies reached each stage.
215	export interface RunCounts {
216	  // Companies returned by search.
217	  readonly searched: number;
218	  // Companies that were enriched.
219	  readonly enriched: number;
220	  // Companies in the final results.
221	  readonly delivered: number;
222	}
223	
224	// Pipeline step names, used for cost and timing breakdowns.
225	export type RunStep = "search" | "validate" | "enrich" | "assess";
226	
227	// Dollars spent in each step.
228	export type RunCosts = Readonly<Record<RunStep, number>>;
229	
230	// Milliseconds spent in each step.
231	export type RunTimings = Readonly<Record<RunStep, number>>;
232	
233	// Record of one agent run.
234	export interface Run {
235	  // Unique ID that ties logs and traces to this run.
236	  readonly trace_id: string;
237	  // The user's plain-language description of who they want to find.
238	  readonly input_description: string;
239	  // Limits this run used.
240	  readonly config: RunConfig;
241	  // Stage-by-stage company counts.
242	  readonly counts: RunCounts;
243	  // US dollars spent per step.
244	  readonly cost_usd_by_step: RunCosts;
245	  // Milliseconds spent per step.
246	  readonly timings_ms_by_step: RunTimings;
247	}
